if(UnityEditor.EditorApplication.isPlaying)throw new System.Exception("Edit mode required");
UnityEngine.GameObject Load(string path)=>UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(path)??throw new System.Exception("Missing asset: "+path);
void AddVisual(string rootPath,string visualPath){var root=UnityEditor.PrefabUtility.LoadPrefabContents(rootPath);try{foreach(var child in root.transform.Cast<UnityEngine.Transform>().Where(t=>t.name=="SH10_Visual").ToArray())UnityEngine.Object.DestroyImmediate(child.gameObject);var visual=UnityEditor.PrefabUtility.InstantiatePrefab(Load(visualPath),root.transform) as UnityEngine.GameObject;visual.name="SH10_Visual";visual.transform.localPosition=UnityEngine.Vector3.zero;visual.transform.localRotation=UnityEngine.Quaternion.identity;visual.transform.localScale=UnityEngine.Vector3.one;UnityEditor.PrefabUtility.SaveAsPrefabAsset(root,rootPath);}finally{UnityEditor.PrefabUtility.UnloadPrefabContents(root);}}
string[] weaponRoots={"Wand_Weapon","Garlic_Weapon","Whip_Weapon","Axe_Weapon","Bible_Weapon","Cross_Weapon"};string[] weaponVisuals={"SH10_MagicWand","SH10_Garlic","SH10_Whip","SH10_Axe","SH10_Bible","SH10_Cross"};for(int i=0;i<weaponRoots.Length;i++)AddVisual("Assets/Prefabs/Weapons/"+weaponRoots[i]+".prefab","Assets/Prefabs/Weapons/"+weaponVisuals[i]+".prefab");
AddVisual("Assets/Prefabs/Items/XP_Gem.prefab","Assets/Prefabs/Items/SH10_XP_Gem.prefab");AddVisual("Assets/Prefabs/Items/HealthChiken.prefab","Assets/Prefabs/Items/SH10_Health_Chicken.prefab");AddVisual("Assets/Prefabs/Items/Chest.prefab","Assets/Prefabs/Items/SH10_Chest.prefab");AddVisual("Assets/Prefabs/Items/Magnet_Pickup.prefab","Assets/Prefabs/Items/SH10_Magnet.prefab");
var bossRoot=UnityEditor.PrefabUtility.LoadPrefabContents("Assets/Prefabs/Weapons/Enemy_Entity.prefab");try{foreach(var child in bossRoot.transform.Cast<UnityEngine.Transform>().Where(t=>t.name=="SH10_Visual").ToArray())UnityEngine.Object.DestroyImmediate(child.gameObject);var bossVisual=UnityEditor.PrefabUtility.InstantiatePrefab(Load("Assets/Prefabs/Bosses/SH10_L01_Boss.prefab"),bossRoot.transform) as UnityEngine.GameObject;bossVisual.name="SH10_Visual";bossVisual.transform.localPosition=UnityEngine.Vector3.zero;bossVisual.transform.localRotation=UnityEngine.Quaternion.identity;bossVisual.transform.localScale=UnityEngine.Vector3.one;UnityEditor.PrefabUtility.SaveAsPrefabAsset(bossRoot,"Assets/Prefabs/Bosses/SH10_L01_BossGameplay.prefab");}finally{UnityEditor.PrefabUtility.UnloadPrefabContents(bossRoot);}
var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var spawner=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Transform>(true)).Select(t=>t.gameObject).First(g=>g.name=="EnemySpawner_Manager").GetComponent<SoulHunter.Gameplay.AI.EnemySpawner>();var so=new UnityEditor.SerializedObject(spawner);so.FindProperty("_bossPrefab").objectReferenceValue=Load("Assets/Prefabs/Bosses/SH10_L01_BossGameplay.prefab");so.ApplyModifiedPropertiesWithoutUndo();var map=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Transform>(true)).Select(t=>t.gameObject).First(g=>g.name=="InfiniteMap_Manager").GetComponent<SoulHunter.Gameplay.Environment.InfiniteMap>();var mapSo=new UnityEditor.SerializedObject(map);mapSo.FindProperty("_chunkPrefab").objectReferenceValue=Load("Assets/Prefabs/Environment/SH10_L01_Ground.prefab");mapSo.ApplyModifiedPropertiesWithoutUndo();UnityEditor.AssetDatabase.SaveAssets();UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);
return new{weapons=weaponRoots.Length,pickups=4,environment="SH10_L01_Ground",boss="SH10_L01_BossGameplay",scene=scene.path};
